body:
> @jalthouse-sfdc just curious, from an attacker perspective couldn't it make some sense to try to match well known JA3 hashes?
@jabedude 

@neslog is correct, this already exists. However, the method they use modifies the TLS Hello packet to match that of the client they are trying to mimic. So even if you used SHA256 or fuzzy hashing, it would come out the same. So changing the hashing algorithm doesn't help in those cases, the best thing to use then is Bro-Sysmon or Zeek-OSQuery to match up the process to the JA3.

I tried on a different site but cloudfare error still showed up. Any ideas?

```
package main

import (
	"net/http"
	"os"
	"github.com/89z/format/crypto"
)

const ja3 = "771,49195-49196-52393-49199-49200-52392-49161-49162-49171-" +
	"49172-156-157-47-53,65281-0-23-35-13-5-16-11-10,29-23-24,0"

func main() {
	req, err := http.NewRequest("GET", "https://vplates.com.au", nil)
	if err != nil {
		panic(err)
	}
	req.Header = http.Header{
		"sec-fetch-dest": {"document"},
		"user-agent":     {"Mozilla/5.0 (Windows NT 10.0; Win64; x64)"},
		"authority":      {"vplates.com.au"},
		"accept":         {"text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9"},
	}
	hello, err := crypto.ParseJA3(ja3)
	if err != nil {
		panic(err)
	}
	res, err := crypto.Transport(hello).RoundTrip(req)
	if err != nil {
		panic(err)
	}
	defer res.Body.Close()
	os.Stdout.ReadFrom(res.Body)
}

```
